312	    private boolean chooseProxySource() {
313	      final DatanodeInfo targetDN = target.getDatanodeInfo();
314	      // if source and target are same nodes then no need of proxy
315	      if (source.getDatanodeInfo().equals(targetDN) && addTo(source)) {
316	        return true;
317	      }
318	      // if node group is supported, first try add nodes in the same node group
319	      if (cluster.isNodeGroupAware()) {
320	        for (StorageGroup loc : reportedBlock.getLocations()) {
321	          if (cluster.isOnSameNodeGroup(loc.getDatanodeInfo(), targetDN)
322	              && addTo(loc)) {
323	            return true;
324	          }
325	        }
326	      }
327	      // check if there is replica which is on the same rack with the target
328	      for (StorageGroup loc : reportedBlock.getLocations()) {
329	        if (cluster.isOnSameRack(loc.getDatanodeInfo(), targetDN) && addTo(loc)) {
330	          return true;
331	        }
332	      }
333	      // find out a non-busy replica
334	      for (StorageGroup loc : reportedBlock.getLocations()) {
335	        if (addTo(loc)) {
336	          return true;
337	        }
338	      }
339	      return false;
