504	    public DBlock getInternalBlock(StorageGroup storage) {
505	      int idxInLocs = locations.indexOf(storage);
506	      if (idxInLocs == -1) {
507	        return null;
508	      }
509	      byte idxInGroup = indices[idxInLocs];
510	      long blkId = getBlock().getBlockId() + idxInGroup;
511	      long numBytes = getInternalBlockLength(getNumBytes(), cellSize,
512	          dataBlockNum, idxInGroup);
513	      Block blk = new Block(getBlock());
514	      blk.setBlockId(blkId);
515	      blk.setNumBytes(numBytes);
516	      DBlock dblk = new DBlock(blk);
517	      dblk.addLocation(storage);
518	      return dblk;
519	    }
